INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('c96e1772-f1a5-4677-9a0f-47024d78a4cd', '21feff02-016d-46e2-bb9d-c27495133b1b', '31. óra: A törtek szorzását alkalmazó feladatok megoldása', 'Törtrész kiszámítása és szöveges feladatok megoldása szorzással.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "46a205df-bc5f-49eb-992f-effd464c7799", "text": "Mennyi 60-nak a 3/4 része? (60 * 3/4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "45"}, {"id": "4bf61bf9-c51b-4fa1-bc4c-ba1e35e62b6e", "text": "Mennyi 100-nak az 1/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "dd4fa267-3c7d-4ce4-bdf4-f94ec7ebe988", "text": "Egy 24 szeletes tortának megették az 1/3-át. Hány szeletet ettek meg?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "36dbf76c-f17f-4675-96eb-edcd5c7a7e0e", "text": "Egy 24 szeletes tortának megették az 1/3-át. Hány szelet maradt?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "16"}, {"id": "b3290a76-1b7f-41e5-80f9-67c63838c30e", "text": "Egy szám törtrészének kiszámításához a számot megszorozzuk a törttel.", "type": "true-false", "options": [{"id": "689933b4-176d-4bf2-89f2-cbb5879aa317", "text": "Igaz", "isCorrect": true}, {"id": "caec0161-d42f-42ef-a4bd-9dbd143d777b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "97e52196-e41d-44af-9ff4-bf1953030f64", "text": "Mennyi 50-nek a 2/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "6144e7b9-a2fe-4b82-bd55-34705d9fd9f3", "text": "Mennyi 1/2 óra percekben? (60 * 1/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('0457ddcd-0532-4b45-8200-aa1aca1a17bd', '21feff02-016d-46e2-bb9d-c27495133b1b', '32. óra: Osztás törttel', 'Törttel való osztás szabálya: szorzás a reciprokával.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "223a64ab-dd29-4840-9f6d-5bd240a9f376", "text": "Hogyan osztunk törttel?", "type": "multiple-choice", "options": [{"id": "1b8a55a7-7597-4a33-99cd-d16367eb2cc1", "text": "Az osztandót megszorozzuk az osztó reciprokával", "isCorrect": true}, {"id": "f31a2489-8bac-45bb-b963-d9e186bf0781", "text": "Az osztandót elosztjuk a nevezővel", "isCorrect": false}, {"id": "0eb803ac-0b82-445a-9f04-b5b5f4436b26", "text": "Mindig 1-et kapunk", "isCorrect": false}, {"id": "9e26d860-060c-4868-ad2f-a956748547e1", "text": "A számlálókat elosztjuk egymással", "isCorrect": false}], "timeLimit": 15}, {"id": "1483f793-1888-40fe-a5cf-0b639665fc07", "text": "Mennyi 2/3 : 4/5? (2/3 * 5/4)", "type": "multiple-choice", "options": [{"id": "5249f7cd-085c-43a5-94a2-d0b6b52f2f02", "text": "10/12 (azaz 5/6)", "isCorrect": true}, {"id": "3d5b5ef5-bfac-4488-a98f-fafbe840bae8", "text": "8/15", "isCorrect": false}, {"id": "825a9dda-2cf2-4643-85aa-729928176481", "text": "6/8", "isCorrect": false}, {"id": "ddfc78da-ae5f-44c7-a692-b2c7516b1a17", "text": "15/8", "isCorrect": false}], "timeLimit": 15}, {"id": "ee05a13b-0b82-4e7c-90d5-438cf33c156e", "text": "Mennyi 1/2 : 1/2?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "50f7d037-803f-4197-b1e5-175130580380", "text": "Ha egy számot 1/2-del osztunk, az eredmény megegyezik a szám 2-vel való szorzatával.", "type": "true-false", "options": [{"id": "fdc45bcc-58f8-42ca-945f-d75ac48420f2", "text": "Igaz ( : 1/2 = * 2)", "isCorrect": true}, {"id": "b3936470-3738-4de6-af3b-01a170ad84b7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d2382400-87ca-463f-b011-4b609af269aa", "text": "Mennyi 6 : 1/3? (6 * 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}, {"id": "e0c97f33-965d-4334-8fbf-81357c499bc5", "text": "Törttel való osztáskor az osztandó nem változik, csak az osztót fordítjuk meg.", "type": "true-false", "options": [{"id": "99a072b8-8bd9-4d07-98d6-09a4b28c7a18", "text": "Igaz", "isCorrect": true}, {"id": "1ef811d2-779c-48dd-a291-a102193546fe", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c0f96d79-74dd-4669-89bf-1ffc760d1500", "text": "Mennyi 3/4 : 3/4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('2fe1234a-27bf-4992-a095-4d64fa876ddf', '21feff02-016d-46e2-bb9d-c27495133b1b', '33. óra: Hétköznapi problémák megoldása törtek osztásának felhasználásával', 'Szöveges feladatok mérésekkel, átdarabolásokkal, törtek osztásával.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "7f99b28a-e317-4d05-bdfa-0b005fe40586", "text": "Hány 1/4 literes pohár tölthető meg 3 liter almaléből? (3 : 1/4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "2e0d4483-e500-46e0-82ce-f47110709a59", "text": "Hány 1/2 kg-os csomag képezhető 5 kg cukorból?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "391a3028-8ad4-4d07-9497-8554a28d25e2", "text": "Egy 6 méteres szalagból 3/4 méteres darabokat vágunk. Hány darabot kapunk? (6 : 3/4 = 6 * 4/3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "b8019fe2-1f98-4bd3-b08e-bd6db4ab0327", "text": "Törtek osztásakor az eredmény lehet nagyobb az eredeti osztandónál, ha az osztó 1-nél kisebb tört.", "type": "true-false", "options": [{"id": "456edd99-bd79-4a88-9d1f-fd1e7c16b6ec", "text": "Igaz", "isCorrect": true}, {"id": "4c6af0c4-6c7e-4bb8-8c2b-10983c66bbef", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ed1e3146-7fdb-4429-b333-385fb9f4d809", "text": "Hány 1/5 méteres darab vágható ki 2 méter anyagból?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "d7572c64-fb01-4dcc-998c-c966c4db795c", "text": "A szöveges feladatoknál az adatok lejegyzése és a mértékegységek egyeztetése elengedhetetlen.", "type": "true-false", "options": [{"id": "3ff0fa19-1b97-4d29-ad1e-ddb5b5aa8ad1", "text": "Igaz", "isCorrect": true}, {"id": "805ac669-811c-4177-afcc-982607b89364", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9da91958-187d-4df5-8037-487e28cc45ed", "text": "Mennyi 4 : 2/3? (4 * 3/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('fbcef08d-b369-49df-9602-d0e0ca1b74cb', '21feff02-016d-46e2-bb9d-c27495133b1b', '34. óra: Gyakorlóóra', 'A törtek szorzásának és osztásának rögzítése, feladatok gyakorlása.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "77a7b893-b85a-4d44-86e5-16c7051e28d6", "text": "Mennyi 3/5 * 5/3?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "19e11dca-0771-473e-ae73-ff57da550086", "text": "Mennyi 4/7 : 2/7? (4/7 * 7/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "99051b2e-5f01-4d36-a843-f8c4f5852366", "text": "Melyik állítás igaz?", "type": "multiple-choice", "options": [{"id": "790cae82-a60d-4d7a-a5f3-186e12f9130e", "text": "Két 1-nél kisebb pozitív tört szorzata kisebb mindkét tényezőnél", "isCorrect": true}, {"id": "08032e24-3de5-4c76-8183-2314004c80e2", "text": "A szorzat mindig nagyobb a tényezőknél", "isCorrect": false}, {"id": "35030d11-df08-44c2-8c61-95c46d252431", "text": "Az osztás mindig kisebb számot ad", "isCorrect": false}, {"id": "ea73d257-5091-43ff-9176-6102331d2104", "text": "Nincs reciproka a 4/5-nek", "isCorrect": false}], "timeLimit": 15}, {"id": "30c80af3-c046-4664-84f4-fb265006c68a", "text": "Mennyi 5/6 * 12? (5 * 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "5aee7ccf-fcf5-4f7f-a763-fba1976c8d55", "text": "A 2/3 osztva 1/3-dal 2-t ad.", "type": "true-false", "options": [{"id": "b61772c0-9822-4ce2-9b18-aba5d18926b3", "text": "Igaz", "isCorrect": true}, {"id": "6ea2b972-9f91-4caf-8ff4-69ac37d90273", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8700bd5c-c67c-45cd-bae2-7bb73c55834d", "text": "Mennyi 3/8 : 3/8?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "9e48699c-cee3-49fb-8e5b-057b42af6cea", "text": "Mennyi 1/4 * 4/5?", "type": "multiple-choice", "options": [{"id": "86a00f52-f624-419a-8694-fd414e7b8953", "text": "1/5", "isCorrect": true}, {"id": "4ba7c879-9747-4f93-97ac-72cadb48733e", "text": "4/20", "isCorrect": false}, {"id": "5ea757c5-4353-4f5a-9721-a18040dc85a1", "text": "1/20", "isCorrect": false}, {"id": "6113f2ad-245c-4acb-a1ab-611523db0213", "text": "4/9", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('8c0b852c-fa72-4534-b342-9bafc13401d5', '21feff02-016d-46e2-bb9d-c27495133b1b', '35. óra: Számonkérés', 'Számonkérés a közönséges törtek műveleteiből (10 kérdés).', 'Matematika', '6. osztály', 'Törtek', '[{"id": "72710b50-d4bd-4d53-bbfe-60bfe0e7a857", "text": "1. Mennyi 2/5 + 1/5?", "type": "multiple-choice", "options": [{"id": "6ff65a47-1d0a-4167-9750-024ee73f50ad", "text": "3/5", "isCorrect": true}, {"id": "6f7890a1-882b-4b56-99db-15bae7f7bc8d", "text": "3/10", "isCorrect": false}, {"id": "890cef23-e61f-496e-8b97-9f51f237a4cf", "text": "2/10", "isCorrect": false}, {"id": "09789363-6ed0-4a92-82ea-6c312e6cb7b8", "text": "1/5", "isCorrect": false}], "timeLimit": 15}, {"id": "39d35351-8e6a-41fc-b330-7a7535f3f171", "text": "2. Mennyi 3/4 - 1/2? (3/4 - 2/4)", "type": "multiple-choice", "options": [{"id": "4df7f88b-d3a7-423f-a6c6-465a9c438e2b", "text": "1/4", "isCorrect": true}, {"id": "c70cf50b-60c9-4481-926e-e3e136adb57e", "text": "2/2", "isCorrect": false}, {"id": "c2be8f3e-188d-4da4-aeea-e149014c75fb", "text": "1/2", "isCorrect": false}, {"id": "1f89cc0d-e605-4989-abed-b3bd4214b153", "text": "2/4", "isCorrect": false}], "timeLimit": 15}, {"id": "924ec400-b70b-4838-8f38-a9c79c67fea4", "text": "3. Mennyi 2/3 * 3/4?", "type": "multiple-choice", "options": [{"id": "ba8a8f92-744e-4595-8453-ca5370cfa2ed", "text": "6/12 (azaz 1/2)", "isCorrect": true}, {"id": "efe5234a-1e34-4c5b-b47d-204971323335", "text": "5/7", "isCorrect": false}, {"id": "23e6117c-6b86-41c3-bf52-80e32c401312", "text": "6/7", "isCorrect": false}, {"id": "7f667740-8754-49b0-a3dd-d8e4a0f05212", "text": "2/4", "isCorrect": false}], "timeLimit": 15}, {"id": "001cbfc5-508d-431b-8b65-bbee36c806b5", "text": "4. Mennyi 1/2 : 1/4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "87e744bf-32f5-4b9f-b3db-cedb489fb047", "text": "5. Mi a 7/8 reciproka?", "type": "multiple-choice", "options": [{"id": "75855314-49ff-4ba5-97c1-d385a90b7478", "text": "8/7", "isCorrect": true}, {"id": "9e6430c9-a6d6-42b6-a913-390b1331fd30", "text": "-7/8", "isCorrect": false}, {"id": "2ba70965-4bc2-424d-94cb-75aadcbf7792", "text": "1/7", "isCorrect": false}, {"id": "307687eb-3c68-42ad-bfe2-8db54112f5c5", "text": "7/8", "isCorrect": false}], "timeLimit": 15}, {"id": "923cee4b-c584-4adc-8eeb-3b40f9429f01", "text": "6. Mennyi 40-nek a 3/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "910a4b72-fdcb-4262-9074-c882c9fdef35", "text": "7. Egy szám és reciproka szorzata 1.", "type": "true-false", "options": [{"id": "ca90f4a6-b868-4d40-a789-3c7998dca21c", "text": "Igaz", "isCorrect": true}, {"id": "767eb182-6009-4138-96ff-0b0c56b0d8cf", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1e5cd313-f5b5-4eab-9980-2e599323fcc2", "text": "8. Mennyi 5 : 1/2?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "e3005669-bdc5-4562-a56c-943d6fc9b2ad", "text": "9. A törtek szorzásakor a számlálót a számlálóval, a nevezőt a nevezővel szorozzuk.", "type": "true-false", "options": [{"id": "eba96f32-ba68-43a3-be16-14b83c89d715", "text": "Igaz", "isCorrect": true}, {"id": "4725d432-1f77-4d32-8801-8a4cfbd53fc2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "79432742-04db-4b09-903d-eac2d754b1f7", "text": "10. Hány negyedből áll 3 egész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('4a733513-83e3-4a9b-a475-08154f2c2a6d', '21feff02-016d-46e2-bb9d-c27495133b1b', '36. óra: Matematikai játékok', 'Matematikai társasjátékok, stratégiák törtekkel, csoport- és páros munka.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "e8596b46-753c-4995-8ca3-21ffac3a096b", "text": "Melyik állítás igaz a matematikai társasjátékokról?", "type": "multiple-choice", "options": [{"id": "baa52cdb-0b6d-4eb0-baba-4958676ea76b", "text": "Fejlesztik a számolási gyorsaságot és a logikai stratégiát", "isCorrect": true}, {"id": "cabda19c-bb43-4f2b-89d6-879ecc9bbb4d", "text": "Nincs közük a matematikához", "isCorrect": false}, {"id": "d81f0835-84c6-4645-92e2-4672dae07ebf", "text": "Kizárólag szerencse kell hozzájuk", "isCorrect": false}, {"id": "257ac183-c219-447e-a53a-beb46dfad72f", "text": "Tiltható az együttműködés", "isCorrect": false}], "timeLimit": 15}, {"id": "4ba123e5-4634-4d8e-a058-ad8ffae88cfc", "text": "A tört domino játékban az egyenlő értékű törteket illesztjük össze.", "type": "true-false", "options": [{"id": "5489d7e8-595e-437b-961a-fcbb5bfd7255", "text": "Igaz", "isCorrect": true}, {"id": "0b42df99-45eb-4210-96ab-fb5e094d9363", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a9c1a912-7897-4a47-b2fe-19d0deecb5f8", "text": "Melyik tört felel meg a 0,5 tizedes törtnek?", "type": "multiple-choice", "options": [{"id": "8491d2dc-bc51-4833-a74c-7419cf6985c1", "text": "1/2", "isCorrect": true}, {"id": "1a251e81-2fa3-4d7f-a7c4-b73843348e69", "text": "1/5", "isCorrect": false}, {"id": "d4f43288-1f40-4b41-8157-235bba4db50a", "text": "2/5", "isCorrect": false}, {"id": "656d94e6-42a8-4309-97a0-62f1cad8bb8c", "text": "5/2", "isCorrect": false}], "timeLimit": 15}, {"id": "70decf76-d63e-4daf-974d-5ad7846b8a82", "text": "Melyik tört felel meg a 0,25-nek?", "type": "multiple-choice", "options": [{"id": "e81864c3-607f-4be1-93e0-58822d5d9aa0", "text": "1/4", "isCorrect": true}, {"id": "e9ef682f-93e4-44aa-be89-e79eb2937155", "text": "1/2", "isCorrect": false}, {"id": "def7d3a2-d2ed-4e43-af44-e7c11b079b47", "text": "2/5", "isCorrect": false}, {"id": "6400904f-4f11-4cc8-a1ba-37dac45eae39", "text": "3/4", "isCorrect": false}], "timeLimit": 15}, {"id": "16cd843f-6778-4adf-8bb4-d52fe118e2e8", "text": "A 3/4 tizedes tört alakja 0,75.", "type": "true-false", "options": [{"id": "0dafa0a6-aacb-4a8d-aafc-dda59bf95e9e", "text": "Igaz", "isCorrect": true}, {"id": "7bf97d2d-4e6e-4f4f-a502-7379e389036e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "53decb27-2791-4a71-b0be-93bbac7e1c30", "text": "Mennyi 0,2 közönséges tört alakban legegyszerűbb formában?", "type": "multiple-choice", "options": [{"id": "05316d7b-130e-4245-9b4e-cdc33d0253d9", "text": "1/5", "isCorrect": true}, {"id": "76a404a4-7b77-43d7-b686-8dd2c7a7e7b3", "text": "2/10", "isCorrect": false}, {"id": "b1de3453-c87c-4d68-bc79-9195fe147bbf", "text": "1/2", "isCorrect": false}, {"id": "c85bbfed-c6bf-444a-aaa3-d26d0100e015", "text": "2/5", "isCorrect": false}], "timeLimit": 15}, {"id": "e6bc7825-cadf-45fd-812a-1295f9e33582", "text": "A tört-bingó játékban a válaszok gyors és pontos kiszámítása a nyerő stratégia.", "type": "true-false", "options": [{"id": "6fcba561-7e10-4fa0-8e75-b7725cf54ced", "text": "Igaz", "isCorrect": true}, {"id": "adf155bf-54e6-4e5b-aa29-658edf48208d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('c57be34d-998d-40be-a66e-5b23bc054db2', '21feff02-016d-46e2-bb9d-c27495133b1b', '37. óra: Mit tanultunk a tizedes törtekről?', 'Tizedes törtek helyi értékei, összeadása és kivonása.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "a4799d09-1e00-45a1-85b6-d5774e510e3d", "text": "Mi a tizedesvessző utáni első helyi érték neve?", "type": "multiple-choice", "options": [{"id": "36860fd8-8c15-45fa-a680-ce033899113f", "text": "Tizedek", "isCorrect": true}, {"id": "4c0064cb-b55d-4a49-ad1e-13a707b2763d", "text": "Századok", "isCorrect": false}, {"id": "bfc259ef-5579-4ce6-bda0-88b221b5ed39", "text": "Ezredeket", "isCorrect": false}, {"id": "5df74262-8382-4ccf-958b-a4edf361805d", "text": "Egyesek", "isCorrect": false}], "timeLimit": 15}, {"id": "261907d0-c82a-422e-b3aa-cf54207cf6d2", "text": "Mi a tizedesvessző utáni második helyi érték neve?", "type": "multiple-choice", "options": [{"id": "b570a515-05eb-4496-9212-0d4d48bad7c4", "text": "Századok", "isCorrect": true}, {"id": "20e03d3d-82cc-42da-a5ea-46711c3e918a", "text": "Tizedek", "isCorrect": false}, {"id": "6a273300-b5e5-400d-b159-003a06f877f5", "text": "Ezredek", "isCorrect": false}, {"id": "fdedc183-9b76-4903-bac1-cb7efc1f15df", "text": "Tízesek", "isCorrect": false}], "timeLimit": 15}, {"id": "ab8975e3-cf6f-4c54-bbc9-b1e3b5a127f5", "text": "Mennyi 3,45 + 2,13?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5.58"}, {"id": "c33f335e-c8bd-495e-a300-8167483a70b3", "text": "Mennyi 7,8 - 3,5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4.3"}, {"id": "b00f5ca6-bc7c-45f8-b356-fa9188503c1e", "text": "Tizedes törtek írásbeli összeadásakor a tizedesvesszőknek egymás alá kell kerülniük.", "type": "true-false", "options": [{"id": "c25807aa-0846-4e2a-8033-3e0a7ddbd583", "text": "Igaz", "isCorrect": true}, {"id": "fb0d24c5-71a0-45cb-8e2d-8fd590b69754", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "35d2126f-364a-4813-ac1f-ffba5f71583b", "text": "Mennyi 5,6 + 4,4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "240e7394-0383-4317-a304-fe39039df221", "text": "Melyik szám nagyobb: 4,05 vagy 4,5?", "type": "multiple-choice", "options": [{"id": "f4de4d2d-3f91-4fca-9c46-72be7c8a764d", "text": "4,5 (mert 4,5 = 4,50)", "isCorrect": true}, {"id": "51d9958e-4283-4a9c-bd10-dda19752fdc5", "text": "4,05", "isCorrect": false}, {"id": "a9a1da5c-8175-4ef3-9151-efb72fe0a2fa", "text": "Egyenlőek", "isCorrect": false}, {"id": "22874ff7-ccfa-4265-b464-de49aa3cdea5", "text": "Nem eldönthető", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('c0aa1797-bb1d-4c68-a342-5cca52575c58', '21feff02-016d-46e2-bb9d-c27495133b1b', '38. óra: Szorzás tizedes törttel', 'Tizedes tört szorzása egész számmal és tizedes törttel, vesszőhely meghatározása.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "b65d6888-4519-4dcb-8c6c-4b82cb2b2826", "text": "Hogyan határozzuk meg a tizedesjegyek számát két tizedes tört szorzatában?", "type": "multiple-choice", "options": [{"id": "39bc8c70-aedc-4c86-a8b2-72395c228e2a", "text": "A tényezők tizedesjegyeinek számát összeadjuk", "isCorrect": true}, {"id": "2c6c6c28-d8e1-463d-b3ff-6f3f547e0f50", "text": "A nagyobbik tényező tizedesjegyeit vesszük", "isCorrect": false}, {"id": "093eb592-5e58-4861-b4ec-dd2bb73a4a0d", "text": "Mindig 1 tizedesjegy lesz", "isCorrect": false}, {"id": "dde48b56-2ea7-4dc0-b26f-1e0d50bc2160", "text": "Nem lesz tizedesjegy", "isCorrect": false}], "timeLimit": 15}, {"id": "69169153-cb07-4bdb-8240-bc47cadc1ca7", "text": "Mennyi 0,3 * 0,2? (3*2 = 6, 2 tizedesjegy)", "type": "multiple-choice", "options": [{"id": "91d82345-0602-4228-bbed-17e424ba9eb9", "text": "0,06", "isCorrect": true}, {"id": "1459009f-d30d-4d14-994a-ef2320e8e60d", "text": "0,6", "isCorrect": false}, {"id": "5b075deb-7adb-462c-b9f9-5957e41f06c7", "text": "6,0", "isCorrect": false}, {"id": "71ea653d-f4a5-472b-bad9-1a77052846b7", "text": "0,006", "isCorrect": false}], "timeLimit": 15}, {"id": "7428da4c-b986-4d13-9c3f-f27eee3e25ff", "text": "Mennyi 2,5 * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "90652401-714e-4c9b-b3b1-2e87bdb6eed1", "text": "Mennyi 1,2 * 0,5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.6"}, {"id": "d49fdd00-4e1d-4faa-8ef3-d4c64e533479", "text": "Ha egy tizedes törtet 10-zel szorzunk, a tizedesvessző egy hellyel jobbra lép.", "type": "true-false", "options": [{"id": "67284c5f-bf4d-41f7-8eda-64028a43bc79", "text": "Igaz", "isCorrect": true}, {"id": "5aca7abb-32a4-4a19-b7a1-a6867a69ba98", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d5a50bc9-7293-440a-a5f9-0238d7e8b8b9", "text": "Mennyi 3,45 * 100?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "345"}, {"id": "7ad69465-fa21-4ff7-b185-6807520bfdfb", "text": "Mennyi 0,1 * 0,1?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.01"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('a7859d87-18ae-4499-bd40-5b6b842d43c6', '21feff02-016d-46e2-bb9d-c27495133b1b', '39. óra: Osztás tizedes törttel', 'Tizedes törttel való osztás szabálya, osztó egész számmá alakítása (bővítés 10-zel, 100-zal).', 'Matematika', '6. osztály', 'Törtek', '[{"id": "0b4bcb08-f754-4f9d-87ef-9d79cef062cd", "text": "Mit teszünk tizedes törttel való osztáskor először?", "type": "multiple-choice", "options": [{"id": "30308119-eb87-4e55-a8b5-aec0c0dcd3a3", "text": "Az osztandót és az osztót is megszorozzuk 10-zel/100-zal, hogy az osztó egész szám legyen", "isCorrect": true}, {"id": "8bc67ffd-957d-41ab-97b1-42a6cc9f86b3", "text": "Elhagyjuk a tizedesvesszőt az osztandóból", "isCorrect": false}, {"id": "d61c28c6-9cc2-45ca-a63f-29867f361b2c", "text": "Kivonjuk az osztót az osztandóból", "isCorrect": false}, {"id": "4d2f4b5f-b742-407c-9127-bdb5c9ef7c94", "text": "Csak az osztót szorozzuk meg", "isCorrect": false}], "timeLimit": 15}, {"id": "acf5a9f4-b142-4960-beba-fe2e0b2cfe14", "text": "Mennyi 2,4 : 0,6? (24 : 6)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "028c3a1b-9d6f-4fa9-b2cb-bf7917205bc1", "text": "Mennyi 1,5 : 0,3? (15 : 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "cd9d603a-607b-48e1-8a42-e0cd00471cac", "text": "Ha egy tizedes törtet 10-zel osztunk, a tizedesvessző 1 hellyel balra lép.", "type": "true-false", "options": [{"id": "7a2ee36a-aaf3-42a1-be5f-000256421a64", "text": "Igaz", "isCorrect": true}, {"id": "b95eb8c3-7a3a-42e9-9e05-1842da237697", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b6b4dca1-7abc-443b-918e-b76054f2c343", "text": "Mennyi 45,6 : 10?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4.56"}, {"id": "0231b020-0b3a-4d3b-8ee2-102cc5e4bfa9", "text": "Mennyi 3,6 : 0,1? (36 : 1)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "4af124cf-f94c-42bf-8732-13fadef07939", "text": "A tizedes törttel való osztást ellenőrizhetjük szorzással.", "type": "true-false", "options": [{"id": "0eefb8ed-d2c6-4ad7-87f4-9c8137e05686", "text": "Igaz", "isCorrect": true}, {"id": "efa72af4-792f-448f-bcdb-6a5111410dcf", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('4b55dbc2-7731-4976-a0cd-aa545d4f9176', '21feff02-016d-46e2-bb9d-c27495133b1b', '40. óra: Hétköznapi problémák megoldása tizedes törtek szorzásának, osztásának felhasználásával', 'Vásárlási, mértékegységes és szöveges feladatok.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "04f153f1-5d4c-42b8-8712-adcd7d96de5d", "text": "1 kg sajt ára 3200 Ft. Mennyibe kerül 0,5 kg sajt? (3200 * 0,5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1600"}, {"id": "05dd9c1a-339b-482e-bcde-90fea02618a6", "text": "Peti 3,5 kg almát vett 400 Ft/kg áron. Hány Ft-ot fizetett?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1400"}, {"id": "15508bf0-b463-45a6-8f97-cae0e429c411", "text": "Egy 4,8 méteres lécet 4 egyenlő darabra vágunk. Hány méter egy darab?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1.2"}, {"id": "21635da0-12d1-4891-90e4-4118327ecf1f", "text": "Ha 0,25 liter üdítő 150 Ft, akkor 1 liter üdítő (4 * 0,25) 600 Ft-ba kerül.", "type": "true-false", "options": [{"id": "c7ec887f-a792-4a38-a35c-eb7264b369e5", "text": "Igaz", "isCorrect": true}, {"id": "0fcdfacf-4952-4d53-9523-77d84824df5c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "884ca1f6-32f5-426a-bab3-22caca1afba8", "text": "Hány liter benzin fér a tankba 12000 Ft-ért, ha 1 liter benzin 600 Ft?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "adf0823a-86b7-4c89-a255-35b7ac4d8f27", "text": "A becslés segít ellenőrizni, hogy a tizedesvesszőt jó helyre tettük-e a végeredményben.", "type": "true-false", "options": [{"id": "3cd8e723-32ef-48ab-8485-6267f3c2d25e", "text": "Igaz", "isCorrect": true}, {"id": "9b4f6447-a723-4b34-824c-fd608cb2a502", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a305618d-0325-42c6-9070-64d1eec96720", "text": "Mennyi 1,5 kg narancs ára, ha 1 kg 800 Ft?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1200"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;